"""Widen the projection guard: judge each fixture on the pair, not the pool.

Idempotent -- safe to run more than once.
"""
from pathlib import Path

h = Path("hitrates.py")
s = h.read_text()

if "MIN_PAIR_LINKS" in s:
    print("hitrates.py already widened")
else:
    a = s.index("PROJECTION_FLOOR = 0.25")
    b = s.index("def rating_pools(")
    s = s[:a] + 'PROJECTION_FLOOR = 0.25\n\n# How many shared opponents two teams need before their ratings may be\n# compared. Within a division every pair clears this comfortably: the Premier\n# League fixtures checked all shared 18. A cross-division pairing joined only\n# by a cup tie scores 0 or 1, which is the case this exists to reject.\nMIN_POOL_LINKS = 2\n\n# Set deliberately low while this is being tuned. The pool test is transitive:\n# two teams can land in one pool through a chain of other clubs, so the bar\n# each *pair* clears is not the bar the pool clears. On real data that made the\n# outcome incoherent -- a Championship pair sharing one opponent kept all 11\n# projections while another sharing two got none, and Malaga v Deportivo, with\n# 22 shared opponents, was rejected outright.\n#\n# So the pair check below is the one that actually decides a fixture, and this\n# constant only governs how the pools are grown. Two is loose on purpose: it\n# rejects the pure cup-tie bridge that caused the Hull City bug and little\n# else, which is the right trade while the honest tuning is still outstanding.\n# See MIN_PAIR_LINKS for the guard that does the real work.\n\n# Shared opponents required between the two sides of a fixture before their\n# projection is trusted. Measured directly on the pair, so it means the same\n# thing for every fixture, unlike the transitive pool test.\n#\n# Four separates the real cases cleanly in the data checked so far: healthy\n# league pairings share 18 to 22, while the cross-division ones that produced\n# nonsense share 0 or 1. It is a provisional number, not a derived one, and\n# wants revisiting against settled results rather than against my judgement.\nMIN_PAIR_LINKS = 4\n\n\n' + s[b:]

    a = s.index("def rating_pools(")
    b = s.index("def league_ratings(")
    s = s[:a] + 'def rating_pools(records_by_team: dict[int, list[dict]],\n                 min_links: int = MIN_POOL_LINKS) -> list[set[int]]:\n    """Split teams into groups that can actually be compared with each other.\n\n    The multiplicative fit only means anything within a set of teams measured\n    against a common standard. Two teams whose matches never overlap sit on\n    separate scales, and nothing in the arithmetic knows that.\n\n    The first version of this asked only whether *a* path existed between two\n    teams, using a plain union-find. That was too weak, and it let the exact\n    bug it was written for straight through. Ratings are fitted from all 20\n    clubs in the division, and each club\'s record covers every competition it\n    played, cup ties included. One FA Cup tie is a path. So Hull City, whose\n    league season was entirely in the Championship, was joined to the Premier\n    League component through a single cup match and waved through as\n    comparable. It projected Ipswich for 6.41 corners against Sunderland\'s\n    3.33 off zero shared opponents, and put Manchester United *below* Hull.\n\n    Existing and being measurable are different things. A single shared\n    fixture is a path but it is nowhere near enough to calibrate one division\n    against another, so what matters is the *weight* of the connection: two\n    teams belong in one pool only if they are joined by at least `min_links`\n    distinct shared opponents, directly or through other teams that clear the\n    same bar. Edges thinner than that are treated as coincidence, which for a\n    cup tie between divisions is exactly what they are.\n    """\n    ids = list(records_by_team)\n    opponents = {\n        t: {r.get("opponent_id") for r in records_by_team[t]\n            if r.get("opponent_id") is not None}\n        for t in ids\n    }\n\n    parent = {t: t for t in ids}\n\n    def find(x):\n        while parent[x] != x:\n            parent[x] = parent[parent[x]]\n            x = parent[x]\n        return x\n\n    def union(a, b):\n        ra, rb = find(a), find(b)\n        if ra != rb:\n            parent[ra] = rb\n\n    # Only join two teams when the overlap in who they have played is thick\n    # enough to calibrate one against the other. Counting a direct meeting as\n    # one link on top of the shared opponents, since playing each other is\n    # itself evidence, just not much of it on its own.\n    for i, a in enumerate(ids):\n        for b in ids[i + 1:]:\n            links = len(opponents[a] & opponents[b])\n            if b in opponents[a] or a in opponents[b]:\n                links += 1\n            if links >= min_links:\n                union(a, b)\n\n    pools: dict[int, set[int]] = {}\n    for t in ids:\n        pools.setdefault(find(t), set()).add(t)\n    return sorted(pools.values(), key=len, reverse=True)\n\n\ndef pool_of(pools: list[set[int]], team_id: int) -> int | None:\n    """Which comparable group a team belongs to, or None if it is unknown."""\n    for i, pool in enumerate(pools):\n        if team_id in pool:\n            return i\n    return None\n\n\n' + s[b:]

    a = s.index("def project_fixture(")
    b = s.index('    home_att = ratings.get("attack"', a)
    s = s[:a] + 'def project_fixture(\n    ratings: dict,\n    home_id: int,\n    away_id: int,\n    names: dict[str, list[str]],\n) -> dict:\n    """Expected value of each stat for this specific fixture.\n\n    Returns {period: {stat: [home_expected, away_expected]}}. Missing ratings\n    simply drop out rather than falling back to the raw average, because a\n    projection built on a guess is worse than no projection.\n    """\n    out: dict = {}\n\n    # Refuse if these two sides were never measured against a common standard.\n    # A rating is a multiplier relative to an average, so comparing two that\n    # were calibrated on different sets of opponents is a category error, not\n    # merely a noisy estimate. Better no projection than a confident wrong\n    # one: the report already falls back to the raw record and says so.\n    #\n    # Judged on the pair directly rather than on pool membership. The pool test\n    # is transitive, so two teams can share a pool through a chain of other\n    # clubs, which made the outcome incoherent on real data: one Championship\n    # pair sharing a single opponent kept every projection while another\n    # sharing two lost all of them. Counting the opponents these two actually\n    # have in common means the same thing for every fixture.\n    opponents = ratings.get("opponents") or {}\n    mine = set(opponents.get(str(home_id)) or [])\n    theirs = set(opponents.get(str(away_id)) or [])\n    if mine and theirs:\n        links = len(mine & theirs)\n        # Having played each other counts, but only for one: it is evidence,\n        # and a single cup tie is not much of it.\n        if away_id in mine or home_id in theirs:\n            links += 1\n        if links < MIN_PAIR_LINKS:\n            return {}\n\n' + s[b:]

    old = '    ratings["pools"] = {str(t): pool_index[t] for t in ids}'
    new = ('    # Who each team has actually played, so a fixture can be judged on the two\n'
           '    # sides in front of it rather than on the pool they were swept into.\n'
           '    ratings["opponents"] = {\n'
           '        str(t): sorted({r.get("opponent_id") for r in records_by_team[t]\n'
           '                        if r.get("opponent_id") is not None})\n'
           '        for t in ids\n'
           '    }\n') + old
    if 'ratings["opponents"]' not in s:
        assert old in s, "could not find the pools assignment"
        s = s.replace(old, new, 1)

    h.write_text(s)
    print("widened hitrates.py")

v = Path("verify.py")
t = v.read_text()
if "gave both answers" in t:
    print("verify.py already updated")
else:
    a = t.index("def check_rating_pools")
    b = t.index("def main() -> None:")
    t = t[:a] + 'def check_rating_pools() -> None:\n    """Teams that never met are not put on one scale, and no count goes <= 0.\n\n    Guards the Hull City bug. A Premier League report projected Hull to score\n    exactly 0.00 goals against Manchester United, because Hull\'s 38 matches\n    were all Championship and the fit normalised both divisions to one mean.\n    Three of ten fixtures in that report were affected, two of them sharing no\n    opponents at all, so this is a class of bug and not one fixture.\n\n    Built as a synthetic two-division league rather than a fixture file,\n    because the failure needs teams that provably never met, and real data\n    stops being a clean example the moment a cup tie connects them.\n    """\n    names = {"ALL": ["Goals", "Corner kicks"]}\n\n    def build(ids, mean_g, mean_c, tag, strengths):\n        recs = {t: [] for t in ids}\n        for a in ids:\n            for b in ids:\n                if a == b:\n                    continue\n                sa, sb = strengths[a], strengths[b]\n                recs[a].append({\n                    "id": a * 1000 + b, "date": "2025-01-01", "competition": tag,\n                    "opponent": f"T{b}", "opponent_id": b, "venue": "home",\n                    "goals_for": 1, "goals_against": 1, "result": "D",\n                    "stats": {"ALL": {"Goals": mean_g * sa / sb,\n                                      "Corner kicks": mean_c * sa / sb}},\n                    "against": {"ALL": {"Goals": mean_g * sb / sa,\n                                        "Corner kicks": mean_c * sb / sa}},\n                })\n        return recs\n\n    top, lower = list(range(1, 9)), list(range(9, 17))\n    strength = {t: 0.6 + 0.16 * (i % 8) for i, t in enumerate(top + lower)}\n    records = {}\n    records.update(build(top, 2.0, 6.0, "Premier League", strength))\n    records.update(build(lower, 1.0, 4.0, "Championship", strength))\n\n    pools = hitrates.rating_pools(records)\n    if len(pools) != 2:\n        print(f"rating pools: expected 2 disconnected groups, got {len(pools)}")\n        sys.exit(1)\n\n    ratings = hitrates.league_ratings(records, names)\n\n    if hitrates.project_fixture(ratings, 9, 1, names) != {}:\n        print("rating pools: projected across divisions that never met")\n        sys.exit(1)\n\n    if not hitrates.project_fixture(ratings, 1, 2, names).get("ALL", {}).get("Goals"):\n        print("rating pools: a normal same-division projection was lost")\n        sys.exit(1)\n\n    # The case the first version of this fix missed. Ratings are fitted from\n    # every club in the division and each club\'s record spans all\n    # competitions, so a single cup tie between divisions creates a path. Bare\n    # connectivity called that comparable and let the bug straight through.\n    bridged = {t: [list(r) for r in [rs]][0][:] for t, rs in records.items()}\n    bridged[9] = list(records[9]) + [{\n        "id": 99999, "date": "2025-02-01", "competition": "FA Cup",\n        "opponent": "T1", "opponent_id": 1, "venue": "away",\n        "goals_for": 0, "goals_against": 3, "result": "L",\n        "stats": {"ALL": {"Goals": 0.0, "Corner kicks": 2.0}},\n        "against": {"ALL": {"Goals": 3.0, "Corner kicks": 9.0}},\n    }]\n    bridged[1] = list(records[1]) + [{\n        "id": 99999, "date": "2025-02-01", "competition": "FA Cup",\n        "opponent": "T9", "opponent_id": 9, "venue": "home",\n        "goals_for": 3, "goals_against": 0, "result": "W",\n        "stats": {"ALL": {"Goals": 3.0, "Corner kicks": 9.0}},\n        "against": {"ALL": {"Goals": 0.0, "Corner kicks": 2.0}},\n    }]\n    if len(hitrates.rating_pools(bridged)) != 2:\n        print("rating pools: one cup tie was enough to merge two divisions")\n        sys.exit(1)\n    if hitrates.project_fixture(\n            hitrates.league_ratings(bridged, names), 9, 1, names) != {}:\n        print("rating pools: projected across divisions joined by one cup tie")\n        sys.exit(1)\n\n    # The same shared-opponent count must always give the same answer. Pool\n    # membership is transitive and did not: on real data one Championship pair\n    # sharing a single opponent kept all 11 projections while another sharing\n    # two lost every one. Judged on the pair, the outcome is a pure function of\n    # the evidence, which is the property that makes the rule explainable.\n    opp = ratings.get("opponents") or {}\n\n    def shared(a, b):\n        m, t = set(opp.get(str(a)) or []), set(opp.get(str(b)) or [])\n        n = len(m & t)\n        if b in m or a in t:\n            n += 1\n        return n\n\n    seen: dict[int, bool] = {}\n    for a, b in [(1, 2), (3, 4), (9, 10), (11, 12), (9, 1), (2, 10), (5, 13)]:\n        count = shared(a, b)\n        projected = bool(hitrates.project_fixture(\n            ratings, a, b, names).get("ALL", {}))\n        if count in seen and seen[count] != projected:\n            print(f"rating pools: {count} shared opponents gave both answers")\n            sys.exit(1)\n        seen[count] = projected\n\n    single = build(list(range(1, 13)), 2.5, 5.0, "Premier League",\n                   {t: 0.7 + 0.05 * t for t in range(1, 13)})\n    solo = hitrates.league_ratings(single, names)\n    if len(hitrates.rating_pools(single)) != 1:\n        print("rating pools: a fully connected league was split")\n        sys.exit(1)\n\n    for home in range(1, 13):\n        for away in range(1, 13):\n            if home == away:\n                continue\n            for stat, pair in hitrates.project_fixture(\n                    solo, home, away, names).get("ALL", {}).items():\n                if min(pair) <= 0:\n                    print(f"rating pools: non-positive projection {stat}={pair}")\n                    sys.exit(1)\n\n    print("rating pools: pair test consistent, cup-tie bridges refused")\n\n\n' + t[b:]
    v.write_text(t)
    print("updated verify.py")
